Description: This Terraform configuration creates an AWS Lambda function named `example_lambda`, including the required IAM execution role and basic CloudWatch Logs permissions. It packages inline Python code into a ZIP file, deploys the Lambda function, and invokes it during Terraform apply using the `aws_lambda_invocation` data source.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

data "archive_file" "example_lambda_zip" {
  type        = "zip"
  output_path = "${path.module}/example_lambda.zip"

  source {
    filename = "lambda_function.py"
    content  = <<EOF
import json

def lambda_handler(event, context):
    return {
        "statusCode": 200,
        "body": json.dumps({
            "message": "Hello from example_lambda!",
            "input": event
        })
    }
EOF
  }
}

